import{_ as t,o,c as a,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const d=JSON.parse('{"title":"Workflow Orchestrator","description":"State machine logic for the 7-step guided automation pipeline.","frontmatter":{"isInternal":true,"type":"Specification","title":"Workflow Orchestrator","description":"State machine logic for the 7-step guided automation pipeline.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/workflow_orchestrator.md","filePath":"specs/features/workflow_orchestrator.md"}'),i={name:"specs/features/workflow_orchestrator.md"};function s(n,e,l,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="workflow-orchestrator-technical-specification" tabindex="-1">Workflow Orchestrator Technical Specification <a class="header-anchor" href="#workflow-orchestrator-technical-specification" aria-label="Permalink to &quot;Workflow Orchestrator Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Workflow Orchestrator automates the complex multi-step process of turning a raw text script into a fully rendered YouTube video. It uses a human-in-the-loop state machine.</p><h2 id="_2-the-7-step-pipeline" tabindex="-1">2. The 7-Step Pipeline <a class="header-anchor" href="#_2-the-7-step-pipeline" aria-label="Permalink to &quot;2. The 7-Step Pipeline&quot;">​</a></h2><ol><li><strong>GENERATE_SCRIPT</strong>: AI expands a prompt into a full script.</li><li><strong>GENERATE_SCENES</strong>: The Director parses the script into structured scenes and generates visual prompts (VibeMap).</li><li><strong>GENERATE_AUDIO</strong>: TTS engines synthesize voiceovers for all lines.</li><li><strong>GENERATE_VISUALS</strong>: Visualizer generates images or video loops for all scenes.</li><li><strong>GENERATE_VIDEO</strong>: Exporter stitches the audio and visuals into a final MP4.</li><li><strong>GENERATE_METADATA</strong>: AI generates YouTube title, description, tags, and a custom thumbnail.</li><li><strong>PUBLISH_YOUTUBE</strong>: Automatically uploads the final MP4 and metadata to a synced YouTube playlist.</li></ol><h2 id="_3-state-machine-logic" tabindex="-1">3. State Machine Logic <a class="header-anchor" href="#_3-state-machine-logic" aria-label="Permalink to &quot;3. State Machine Logic&quot;">​</a></h2><ul><li><strong>Guided Mode</strong>: Pauses at specific gates (e.g., after scene generation, after audio) to allow the user to approve or regenerate before proceeding.</li><li><strong>Auto-Pilot Mode</strong>: Runs all steps sequentially without human intervention.</li><li>The state is persisted in Firestore under <code>scriptData.workflowState</code> so it survives browser refreshes.</li></ul>',7)])])}const f=t(i,[["render",s]]);export{d as __pageData,f as default};
